/* ==========================================================================
   Gaps in the existing modules, closed after the full specification review:
   - Dashboard: a "Compliance management" section with legal compliance,
     training, appointments, risks, audits, contractors, emergency, PPE,
     hazardous substances and document expiry — each opens its records.
   - Reports: legal compliance, risk register, training matrix, appointments
     register (with digital acceptance), PPE issues, hazardous substances,
     contractor compliance and a management review summary.
   - Incidents: direct causes, underlying causes and contributing factors.
   - Audits: checklist items can be linked to legal requirements; the legal
     requirement shows the latest audit result for its linked items.
   - Documents: expiry date (separate from the review date) with reminders.
   ========================================================================== */
'use strict';

/* ---------------- Dashboard: compliance management ---------------- */
function complianceSection() {
  const sid = S.ui.site, tiles = [];
  const add = (area, html) => { if (!AREA_OF[area] || canArea(area)) tiles.push(html); };
  if (typeof legalCounts === 'function') { const c = legalCounts(legalReqs()); add('legal', kpi('Legal compliance', c.pct == null ? '—' : c.pct + '%', `${c.compliant} compliant · ${c.partial} partial · ${c.non} non-compliant · ${c.notAssessed} not assessed`, c.pct == null ? 'blue' : scoreColour(c.pct), '#/legal', 'scale')); }
  if (typeof trainingSummary === 'function') { const t = trainingSummary(trainees()); add('training', kpi('Training up to date', t.pct == null ? '—' : t.pct + '%', `${t.missing} missing · ${t.expired} expired · ${t.expiring} expiring`, t.pct == null ? 'blue' : scoreColour(t.pct), '#/training/matrix?fstatus=gaps', 'checkCircle')); }
  if (typeof appointments === 'function') { const A = appointments(), w = A.filter(aptOpen).length, d = A.filter(a => a.status === 'Declined').length; add('people', kpi('Appointments awaiting acceptance', w, `${d} declined · ${A.filter(a => aptStatus(a) === 'Active').length} active`, w || d ? 'amber' : 'green', '#/people/appointments?fflag=open', 'user')); }
  if (typeof raList === 'function') { const rows = raList().filter(a => a.status !== 'Superseded').flatMap(a => (a.rows || [])), hi = rows.filter(r => { const b = rBand(rowRisk(r)); return b && RM().bands.indexOf(b) >= RM().bands.length - 2; }).length, od = raList().filter(raOverdue).length; add('risk', kpi('High and critical risks', hi, `${od} risk assessment review(s) overdue`, hi ? 'red' : od ? 'amber' : 'green', '#/risk/matrix', 'risk')); }
  { const P = (S.auditPlans || []).filter(x => !x.paused && inSite(x, sid)), up = P.filter(x => daysTo(x.nextDue) >= 0 && daysTo(x.nextDue) <= 30).length, od = P.filter(x => daysTo(x.nextDue) < 0).length; add('audits', kpi('Upcoming audits', up, `next 30 days · ${od} overdue`, od ? 'red' : 'blue', '#/audits/programme', 'shield')); }
  if (typeof contractors === 'function') { const C = contractors().filter(c => c.status !== 'Inactive'), n = C.filter(c => conCompliance(c) === 'Not compliant').length; add('contractors', kpi('Contractors not compliant', n, `of ${C.length} active`, n ? 'red' : 'green', '#/contractors?fcomp=Not%20compliant', 'building')); }
  if (typeof emGaps === 'function') { const s = orgSites().filter(x => sid === 'ALL' || x.id === sid), g = s.filter(x => emGaps(x.id).length).length, d = s.filter(x => daysTo(drillDue(x.id)) < 0).length; add('emergency', kpi('Emergency preparedness', g ? `${g} branch${g > 1 ? 'es' : ''} with gaps` : 'In order', `${d} branch(es) with a drill overdue`, g ? 'amber' : 'green', '#/emergency', 'siren')); }
  { const docs = S.documents.filter(d => inSite(d, sid) && docActive(d) && d.expires), ex = docs.filter(d => daysTo(d.expires) < 0).length, soon = docs.filter(d => daysTo(d.expires) >= 0 && daysTo(d.expires) <= 30).length; add('documents', kpi('Documents expiring', soon, `${ex} expired`, ex ? 'red' : soon ? 'amber' : 'green', '#/documents', 'docs')); }
  if (typeof subFlags === 'function') { const n = subs().filter(x => subFlags(x).length).length; add('substances', kpi('Hazardous substances with gaps', n, 'No SDS, review due, no risk assessment…', n ? 'amber' : 'green', '#/substances?fflag=any', 'flask')); }
  if (typeof ppeStatus === 'function') { let o = 0; ppePeople().forEach(x => ppeReqFor(x).forEach(r => { if (['Outstanding', 'Replacement due'].includes(ppeStatus(x.id, r.ppe))) o++; })); add('ppe', kpi('PPE outstanding or due', o, 'Issue or replace', o ? 'amber' : 'green', '#/ppe/register', 'hardhat')); }
  return tiles.length ? `<h3 class="dash-sec">${icon('scale', 'sm')} Compliance management</h3><div class="kpis kpis-8 dash-comp">${tiles.join('')}</div>` : '';
}
const _dashBeforeGaps = ROUTES.dashboard;
ROUTES.dashboard = (p, q) => { const r = _dashBeforeGaps(p, q); if (!r || !r.html) return r; const k = r.html.indexOf('Trends — last 12 months'); const h = k > 0 ? r.html.lastIndexOf('<h3 class="dash-sec">', k) : -1;
  if (h > 0) r.html = r.html.slice(0, h) + complianceSection() + r.html.slice(h); return r; };

/* ---------------- Reports for the new modules ---------------- */
REPORTS.push(['legalrep', 'Legal compliance register'], ['riskrep', 'Risk register'], ['trainrep', 'Training matrix'], ['aptrep', 'Legal appointments & digital acceptance'], ['pperep', 'PPE issue report'], ['hcsrep', 'Hazardous substances register'], ['conrep', 'Contractor compliance'], ['mgmtreview', 'Management review summary']);
const _buildReportBeforeGaps = buildReport;
buildReport = function (key) {
  const sid = S.ui.site, B = (t, tone) => H(badge(t, tone || 'grey', true), t);
  switch (key) {
    case 'legalrep': { const L = legalReqs(), c = legalCounts(L); return { desc: 'Every legal requirement with its applicability, status, responsible person, evidence and next review. The status is what the assessor recorded; it does not guarantee legal compliance.', pre: `<div class="btn-row mb">${cbadge('Compliant')} <b>${c.compliant}</b> ${cbadge('Partially compliant')} <b>${c.partial}</b> ${cbadge('Non-compliant')} <b>${c.non}</b> ${cbadge('Not assessed')} <b>${c.notAssessed}</b> · legal compliance <b>${c.pct == null ? '—' : c.pct + '%'}</b></div>`,
      ...tableRep(['Reference', 'Legislation', 'Section', 'Requirement', 'Branches', 'Responsible', 'Applicability', 'Status', 'Evidence', 'Next review'], L.map(r => { const l = legOf(r), it = legItem(r), a = lastAssess(r); return [r.id, l ? l.short || l.name : '', it ? it.ref : '', r.title, sitesLabel(r.sites), r.owner ? pname(r.owner) : 'Not allocated', r.applicability, H(cbadge(lrStatus(r)), lrStatus(r)), (r.evidence || []).length, a && a.nextReview ? fmt(a.nextReview) : '']; })) }; }
    case 'riskrep': { const rows = raList().filter(a => a.status !== 'Superseded').flatMap(a => (a.rows || []).map(r => ({ a, r }))); return { desc: 'Every assessed hazard with its initial and residual risk, controls and acceptance.',
      ...tableRep(['Assessment', 'Branch', 'Hazard', 'Category', 'Initial risk', 'Residual risk', 'Open controls', 'Residual risk accepted', 'Review'], rows.map(({ a, r }) => [a.id + ' ' + a.title, sname(a.site), r.title, r.category || '', H(rChip(r.initial), rScore(r.initial) + ' ' + rBand(r.initial).name), r.residual && r.residual.l ? H(rChip(r.residual), rScore(r.residual) + ' ' + rBand(r.residual).name) : '—', (r.controls || []).filter(c => !['Implemented', 'Verified'].includes(c.status)).length, r.accepted ? pname(r.accepted.by) + ' ' + fmt(r.accepted.on) : 'No', a.reviewDate ? fmt(a.reviewDate) : ''])) }; }
    case 'trainrep': { const T = trainees().filter(x => requiredFor(x).length); return { desc: 'Each person\'s required training and its status.', ...tableRep(['Employee', 'Job title', 'Branch', 'Course', 'Required because', 'Status', 'Valid until'], T.flatMap(x => requiredFor(x).map(q => { const s = trStatus(x.id, q.course), r = lastRecord(x.id, q.course); return [x.name, x.jobTitle, sname(x.site), course(q.course).name, q.why, H(badge(s, TR_TONE[s], true), s), r && r.expires ? fmt(r.expires) : '']; }))) }; }
    case 'aptrep': { const A = appointments(); return { desc: 'All legal appointments (digital and uploaded) with the digital acceptance record.', ...tableRep(['Appointment', 'Employee', 'Number', 'Type', 'Branch', 'Method', 'Effective', 'End', 'Status', 'Acknowledged', 'Accepted', 'Signed (uploaded)'], A.map(a => { const x = person(a.person) || {}; return [a.id, x.name, x.empNo || '', aptType(a).name, sname(a.site), a.method, fmt(a.effective), a.end ? fmt(a.end) : '', aptStatus(a), a.ack ? fmtTs(a.ack.ts) : '', a.accept ? fmtTs(a.accept.ts) + ' by ' + a.accept.name : '', a.signedOn ? fmt(a.signedOn) : '']; })) }; }
    case 'pperep': { const I = (S.ppeIssues || []).filter(i => i.org === S.ui.org && (sid === 'ALL' || (person(i.person) || {}).site === sid)).sort((a, b) => b.date.localeCompare(a.date)); return { desc: 'PPE issued, with replacement dates and acknowledgement.', ...tableRep(['Date', 'Employee', 'Item', 'Qty', 'Reason', 'Replace by', 'Acknowledged'], I.map(i => [fmt(i.date), pname(i.person), (ppeType(i.ppe) || {}).name, i.qty, i.reason, i.replaceBy ? fmt(i.replaceBy) : '', i.ack ? fmtTs(i.ack.ts) : 'No'])) }; }
    case 'hcsrep': return { desc: 'Hazardous substances with their safety data sheets, controls and gaps.', ...tableRep(['Substance', 'Branch', 'Location', 'Hazard classes', 'SDS', 'SDS review', 'Risk assessment', 'Gaps'], subs().map(x => [x.name, sname(x.site), x.location, (x.ghs || []).join(', '), sdsDoc(x) ? sdsDoc(x).number : x.sdsFile ? x.sdsFile.name : 'Missing', x.sdsReview ? fmt(x.sdsReview) : '', x.ra || '—', subFlags(x).join(', ') || 'None'])) };
    case 'conrep': return { desc: 'Contractors and the state of their required documents.', ...tableRep(['Contractor', 'Kinds of work', 'Status', 'Compliance', 'Documents not in order', 'Employees inducted'], contractors().map(c => [c.name, (c.work || []).join(', '), c.status, H(badge(conCompliance(c), conCompliance(c) === 'Compliant' ? 'green' : 'red', true), conCompliance(c)), conGaps(c).map(r => r.name + ' (' + docState(c, r).toLowerCase() + ')').join('; ') || 'None', `${(c.employees || []).filter(e => e.induction).length} of ${(c.employees || []).length}`])) };
    case 'mgmtreview': { const c = compliance(sid), L = legalCounts(legalReqs()), T = trainingSummary(trainees()), A = appointments(), acts = S.actions.filter(a => inSite(a, sid));
      const rows = [['Control score (documents, assets, actions, incidents)', c.overall + '%'], ['Legal compliance (assessed applicable requirements)', L.pct == null ? 'Not assessed' : L.pct + '%'], ['Legal requirements non-compliant / not assessed', `${L.non} / ${L.notAssessed}`], ['Training up to date', T.pct == null ? '—' : T.pct + '%'], ['Appointments active / awaiting acceptance / declined', `${A.filter(a => aptStatus(a) === 'Active').length} / ${A.filter(aptOpen).length} / ${A.filter(a => a.status === 'Declined').length}`],
        ['High and critical risks', raList().filter(a => a.status !== 'Superseded').flatMap(a => a.rows || []).filter(r => { const b = rBand(rowRisk(r)); return b && RM().bands.indexOf(b) >= RM().bands.length - 2; }).length], ['Risk assessment reviews overdue', raList().filter(raOverdue).length], ['Corrective actions open / overdue', `${acts.filter(actionOpen).length} / ${acts.filter(actionOverdue).length}`],
        ['Incidents in the last 12 months', S.incidents.filter(i => inSite(i, sid) && daysTo(i.date) > -365).length], ['Audits overdue', (S.auditPlans || []).filter(x => !x.paused && inSite(x, sid) && daysTo(x.nextDue) < 0).length], ['Contractors not compliant', contractors().filter(c => conCompliance(c) === 'Not compliant').length], ['Branches with emergency gaps', orgSites().filter(x => (sid === 'ALL' || x.id === sid) && emGaps(x.id).length).length]];
      return { desc: 'One page for the management review: the key figures from every module. Figures come from the records; they do not guarantee legal compliance.', ...tableRep(['Measure', 'Value'], rows) }; }
  }
  return _buildReportBeforeGaps(key);
};

/* ---------------- Incidents: direct, underlying and contributing causes ---------------- */
const _incBeforeGaps = ROUTES.incidents;
ROUTES.incidents = (p, q) => { const r = _incBeforeGaps(p, q); if (!r || !r.html || !p[0] || !/^INC-/.test(p[0])) return r; const i = byId('incidents', p[0]); if (!i || i.status === 'Reported') return r;
  const c = i.causes || {}, L = (k, t) => `<div><span class="t-sub">${t}</span>${(c[k] || []).length ? `<ul class="plain-list">${c[k].map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<div class="muted">Not recorded</div>'}</div>`;
  const card = `<div class="card"><div class="card-head"><h2>Causes</h2>${can('incident.investigate') && i.status !== 'Closed' ? `<button class="btn sm" data-act="incCauses" data-id="${i.id}">${icon('edit', 'sm')} Edit</button>` : ''}</div><div class="card-body ra-grid">${L('direct', 'Direct causes (what immediately caused it)')}${L('underlying', 'Underlying causes (why those conditions or acts existed)')}<div class="full">${L('contributing', 'Contributing factors')}</div></div></div>`;
  const k = r.html.indexOf('<div class="detail"><div class="stack">'); if (k >= 0) { const at = k + '<div class="detail"><div class="stack">'.length; r.html = r.html.slice(0, at) + card + r.html.slice(at); } return r; };
ACT.incCauses = (el) => { const i = byId('incidents', el.dataset.id), c = i.causes || {}; openModal({ title: 'Causes', sub: `${i.id} — one per line. The root cause stays in the investigation.`, size: 'wide', body: `<div class="form-grid">${fld({ name: 'direct', label: 'Direct causes', type: 'textarea', rows: 3, value: (c.direct || []).join('\n'), full: true, placeholder: 'e.g. Pedestrian stepped into the aisle' })}${fld({ name: 'underlying', label: 'Underlying causes', type: 'textarea', rows: 3, value: (c.underlying || []).join('\n'), full: true, placeholder: 'e.g. No physical separation of walkways' })}${fld({ name: 'contributing', label: 'Contributing factors', type: 'textarea', rows: 3, value: (c.contributing || []).join('\n'), full: true, placeholder: 'e.g. Poor lighting at night shift' })}</div>`,
  buttons: [{ label: 'Save', cls: 'primary', onClick: m => { const v = readForm(m), sp = t => (t || '').split('\n').map(x => x.trim()).filter(Boolean); i.causes = { direct: sp(v.direct), underlying: sp(v.underlying), contributing: sp(v.contributing) }; log(`Recorded causes for ${i.id}`, '#/incidents/' + i.id); save(); rerender(); } }] }); };

/* ---------------- Audits ↔ legal requirements ---------------- */
// audit checklist builder: each item can be linked to a legal requirement of this company
const _builderBeforeGaps = auditBuilder;
auditBuilder = function (id, q) { const r = _builderBeforeGaps(id, q); if (!AB || !r || !r.html) return r; const L = (S.legalReqs || []).filter(x => x.org === S.ui.org);
  r.html = r.html.replace(/<label>Weight <select class="ab-in" data-s="(\d+)" data-i="(\d+)" data-k="weight">/g, (m0, si, ii) => { const it = AB.sections[+si].items[+ii]; return `<label class="ab-lr">Legal requirement <select class="ab-in" data-s="${si}" data-i="${ii}" data-k="legalReq"><option value="">— None —</option>${L.map(x => `<option value="${x.id}" ${it.legalReq === x.id ? 'selected' : ''}>${esc(x.id + ' ' + x.title)}</option>`).join('')}</select></label>` + m0; }); return r; };
const _abSaveBeforeGaps = ACT.abSave;
ACT.abSave = () => { const keep = {}; (AB ? AB.sections : []).forEach(s => s.items.forEach(i => { if (i.legalReq) keep[i.id] = i.legalReq; }));
  _abSaveBeforeGaps(); (S.auditTemplates || []).forEach(t => (t.revisions || []).forEach(rv => rv.sections.forEach(s => s.items.forEach(i => { if (keep[i.id]) i.legalReq = keep[i.id]; })))); save(); };
function lrAuditResults(lrId) { const out = []; (S.audits || []).filter(a => a.status === 'Completed').forEach(a => a.template.sections.forEach(s => s.items.filter(i => i.legalReq === lrId).forEach(i => out.push({ a, i, an: a.answers[i.id] || {} })))); return out.sort((x, y) => y.a.date.localeCompare(x.a.date)); }
const _legalBeforeGaps = ROUTES.legal;
ROUTES.legal = (p, q) => { const r = _legalBeforeGaps(p, q); if (!r || !r.html || !p[0] || !/^LR-/.test(p[0])) return r; const R = lrAuditResults(p[0]); const RES = { C: ['Compliant', 'green'], P: ['Partially', 'amber'], N: ['Not compliant', 'red'], NA: ['N/A', 'grey'] };
  const card = `<div class="card"><div class="card-head"><h2>Audit results</h2><span class="ch-sub">Audit checklist items linked to this requirement</span></div><div class="card-body flush">${R.length ? `<ul class="link-list">${R.slice(0, 8).map(x => `<li><div class="ll-main"><a href="#/audits/${x.a.id}" class="mono">${x.a.id}</a> ${esc(x.i.text)}<div class="t-sub">${esc(x.a.template.title)} · ${esc(sname(x.a.site))} · ${fmt(x.a.date)}${x.an.note ? ' · ' + esc(x.an.note) : ''}</div></div>${x.an.r ? badge(RES[x.an.r][0], RES[x.an.r][1], true) : ''}</li>`).join('')}</ul>` : '<div class="card-body muted">No audit checklist items are linked to this requirement yet. Link them in Administration → Audit checklists.</div>'}</div></div>`;
  const k = r.html.indexOf('<div class="card"><div class="card-head"><h2>Corrective actions</h2>'); if (k >= 0) r.html = r.html.slice(0, k) + card + r.html.slice(k); return r; };

/* ---------------- Document expiry reminders ---------------- */
const _myTasksBeforeGaps = myTasks;
myTasks = function () { const out = _myTasksBeforeGaps(); S.documents.filter(d => inSite(d, 'ALL') && d.owner === S.ui.user && docActive(d) && d.expires && daysTo(d.expires) <= 30).forEach(d => out.push({ title: `${daysTo(d.expires) < 0 ? 'Expired' : 'Expiring'}: ${d.number} ${d.title}`, sub: `Expiry date ${fmt(d.expires)} — upload the renewed document`, link: '#/documents/' + d.id, sev: daysTo(d.expires) < 0 ? 'red' : 'amber' })); return out; };
MIGRATIONS.push(() => { if (S.migr && S.migr.gaps) return; S.migr = S.migr || {}; S.migr.gaps = true;
  const d = byId('documents', 'DOC-021'); if (d && !d.expires) d.expires = addDays(TODAY, 20);   // electrical certificate of compliance: demo expiry
});
